def alarm_clock(day, on_vacation):
    """Returns as a string the time the alarm time
       on a given day and holiday-status (True/False)
    """
    is_weekend = ((day % 6) == 0)
    if is_weekend and on_vacation:
        str_alarm = "off"
    elif not is_weekend and not on_vacation:
        str_alarm = "7:00"
    else:
        str_alarm = "10:00"
    return str_alarm

def alarm_clock(day, on_vacation):
